/**
 * Schemas feature:
 *  - associates the bundled JSON schemas (schemas/*.schema.json, generated by
 *    scripts/generate-schemas.py) with Jumpstarter YAML config files through
 *    the Red Hat YAML extension (silently skipped when it is absent);
 *  - contributes the commands jumpstarter.newClientConfig and
 *    jumpstarter.newExporterConfig, which scaffold a minimal valid config in
 *    the Jumpstarter config home and open it in the editor.
 */

import * as vscode from "vscode";
import * as path from "path";
import { Services } from "../services";
import {
  buildClientScaffold,
  buildExporterScaffold,
  configFilePathForAlias,
  driverTypesFromList,
  validateAlias,
} from "./schemas/logic";
import { activateYamlAssociation } from "./schemas/yamlAssociation";

export function registerSchemas(context: vscode.ExtensionContext, services: Services): void {
  context.subscriptions.push(
    activateYamlAssociation({
      configHome: services.configWatcher.configHome,
      schemaPath: (fileName) => context.asAbsolutePath(path.join("schemas", fileName)),
      loadDrivers: async () => {
        if (!services.jmp.hasCapability("driverSchema")) {
          return [];
        }
        return services.jmp.driverSchemas();
      },
      onDidChangeEnvironment: services.jmp.onDidChangeAvailability,
      log: (message) => services.jmp.log(message),
    }),
  );

  context.subscriptions.push(
    vscode.commands.registerCommand("jumpstarter.newClientConfig", () =>
      newConfig("client", services),
    ),
    vscode.commands.registerCommand("jumpstarter.newExporterConfig", () =>
      newConfig("exporter", services),
    ),
  );
}

async function newConfig(kind: "client" | "exporter", services: Services): Promise<void> {
  const alias = await vscode.window.showInputBox({
    title: kind === "client" ? "New Jumpstarter Client Config" : "New Jumpstarter Exporter Config",
    prompt: `Alias for the new ${kind} config (becomes ${kind === "client" ? "clients" : "exporters"}/<alias>.yaml)`,
    placeHolder: kind === "client" ? "my-client" : "my-exporter",
    validateInput: validateAlias,
  });
  if (alias === undefined || alias === "") {
    return; // cancelled
  }

  const filePath = configFilePathForAlias(services.configWatcher.configHome, kind, alias);
  const fileUri = vscode.Uri.file(filePath);

  if (await fileExists(fileUri)) {
    const open = "Open Existing";
    const choice = await vscode.window.showWarningMessage(
      `A ${kind} config named "${alias}" already exists at ${filePath}.`,
      open,
    );
    if (choice === open) {
      await vscode.window.showTextDocument(await vscode.workspace.openTextDocument(fileUri));
    }
    return;
  }

  const content =
    kind === "client"
      ? buildClientScaffold({ alias })
      : buildExporterScaffold({ alias, driverTypes: await installedDriverTypes(services) });

  try {
    await vscode.workspace.fs.createDirectory(vscode.Uri.file(path.dirname(filePath)));
    await vscode.workspace.fs.writeFile(fileUri, Buffer.from(content, "utf8"));
  } catch (err) {
    void vscode.window.showErrorMessage(
      `Jumpstarter: failed to create ${filePath}: ${err instanceof Error ? err.message : String(err)}`,
    );
    return;
  }

  await vscode.window.showTextDocument(await vscode.workspace.openTextDocument(fileUri));
}

/** Best-effort list of installed driver types for the exporter scaffold comment. */
async function installedDriverTypes(services: Services): Promise<string[]> {
  try {
    return driverTypesFromList(await services.jmp.driverList());
  } catch {
    // jmp missing / broken env — the scaffold works fine without suggestions,
    // and JmpService already logged the failure to the output channel.
    return [];
  }
}

async function fileExists(uri: vscode.Uri): Promise<boolean> {
  try {
    await vscode.workspace.fs.stat(uri);
    return true;
  } catch {
    return false;
  }
}
